// ===== validate input + build Gemini translate request =====
// แอป (artwork_check/translate.py) ส่ง POST JSON {"lines": [...]}
const item = $input.first().json;
const body = item.body ?? item;

let lines = body.lines;
let valid = true;
let error = '';

if (!Array.isArray(lines)) {
  valid = false;
  error = "missing JSON field 'lines' (array of strings)";
  lines = [];
} else {
  lines = lines.map((l) => (l == null ? '' : String(l)));
  if (lines.length === 0) { valid = false; error = "'lines' is empty"; }
  if (lines.length > 400) {
    valid = false;
    error = `too many lines: ${lines.length} (limit 400)`;
  }
}

const PROMPT = "You translate food-packaging label text to English for proofing.\nYou receive a JSON array of text lines in mixed languages (Arabic,\nSpanish, Thai, English, ...).\n\nRULES:\n- Return EXACTLY one English translation per input line, in the SAME\n  order, as a JSON array of the SAME length.\n- If a line is already English, return it unchanged.\n- If a line is only digits / codes / units (e.g. \"16785\", \"200 gm\",\n  \"70%\"), return it unchanged.\n- Translate the meaning faithfully and concisely. No notes, no comments.\n- Do NOT correct spelling \u2014 translate the text as written.\n\nReturn ONLY JSON: {\"translations\": [\"<en line 1>\", \"<en line 2>\", ...]}";

const responseSchema = {
  type: 'OBJECT',
  properties: {
    translations: { type: 'ARRAY', items: { type: 'STRING' } },
  },
  required: ['translations'],
};

const geminiRequest = !valid ? null : {
  contents: [{
    role: 'user',
    parts: [
      { text: PROMPT },
      { text: 'INPUT LINES (JSON array):\n' + JSON.stringify(lines) },
    ],
  }],
  generationConfig: {
    temperature: 0,
    topP: 1,
    maxOutputTokens: 8192,
    responseMimeType: 'application/json',
    responseSchema,
    thinkingConfig: { thinkingBudget: 0 },
  },
};

return [{
  json: { valid, error, line_count: lines.length, gemini_request: geminiRequest },
}];

// ===== parse Gemini response → {"translations": [...]} =====
const r = $input.first().json;
if (r.error) throw new Error(`Gemini API error: ${JSON.stringify(r.error)}`);

const cand = (r.candidates ?? [])[0] ?? {};
const raw = ((cand.content ?? {}).parts ?? [])
  .map((p) => p.text ?? '').join('\n').trim();

let s = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
let parsed = null;
try { parsed = JSON.parse(s); }
catch (e) {
  const i = s.indexOf('{'), j = s.lastIndexOf('}');
  if (i >= 0 && j > i) { try { parsed = JSON.parse(s.slice(i, j + 1)); } catch (e2) {} }
}

let translations = [];
let warning;
if (parsed && Array.isArray(parsed.translations)) {
  translations = parsed.translations.map((t) => (t == null ? '' : String(t)));
} else if (Array.isArray(parsed)) {
  translations = parsed.map((t) => (t == null ? '' : String(t)));
} else {
  warning = 'model did not return a translations array';
}

return [{
  json: {
    translations,
    ...(warning ? { warning } : {}),
    usage: r.usageMetadata ?? null,
  },
}];
